{
  "spells": [
    {
      "id": "spell_wind_13",
      "theory": "盘旋风柱以松脂为引，在近地空气中搓出一股上升旋流。施术者先让魔力沿螺旋轨迹缠住气流，再借松脂的黏性把松散尘土和轻质物件卷进柱心。风柱只托得住草屑、纸片和羽毛一类轻物，旋涡边缘却会顺手带走未固定的零碎，因此场地越整洁越容易控制。它不会凭空搬动箱笼或武器，也不能让人浮空。",
      "casting": "左手托住一小块松脂，右手在空气中由低向高画螺旋，每画一圈就向旋心送一次魔力，待草屑开始绕行时松开松脂。",
      "failure": "松脂未完全融散时，风柱会忽高忽低地打转，把附近纸片和干草卷得到处都是，却托不起原本瞄准的轻物，还可能让施术者衣袖缠上碎屑。",
      "counters": [
        "用湿布或压石盖住松散物品，旋流就找不到足够的轻质负载。",
        "在风柱底部撒一把湿沙，沙粒会打乱螺旋轨迹使旋流提前散开。"
      ],
      "socialConsequences": "集市收摊者和码头理货人有时会请人用风柱快速聚拢散落的轻货，省去弯腰捡拾的工夫。但邻近摊主会担心自家纸签和布头被卷走，通常要求先清空周边。若有人的轻质货物被卷损，乡约常按实际损失调解赔偿，而不是一律重罚；故意把风柱对准他人货堆则另算侵占。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时旋流忽强忽弱，轻物常在半空打转后落地。",
        "熟练到百点后，能稳定卷起纸片而不惊动邻近布头。",
        "三百点以上可让风柱沿指定窄道移动，减少外溢。",
        "六百点后旋心位置精确，仍只托起规定范围内的轻物。"
      ]
    },
    {
      "id": "spell_wind_14",
      "theory": "逆风环把魔力编成一层横贯道路的环形气流，令穿过者持续受到迎面阻力。松脂被磨成细粉撒入空中，作为气流的附着核心，使环带在低空维持稳定。它不制造伤害，只是让脚步和车轮变得迟滞，对同行者同样生效。环带宽度和高度受施术时划定的边界限制，不能凭空移走重物或把人推倒。",
      "casting": "双手各捏一点松脂粉，在道路两侧各画一道半弧，两弧合拢时向环带内送入魔力，待尘土贴地横走便可停手。",
      "failure": "两弧未对齐时，逆风环会偏向一侧，把尘土和落叶吹进路边沟渠，穿行阻力时有时无，反而让行人误判路况而绊倒。",
      "counters": [
        "沿环带边缘插一排湿木桩，湿气会削弱气流附着的松脂粉。",
        "从侧方投掷一捆干草，草束穿过环带时会带走部分附着核心。"
      ],
      "socialConsequences": "河岸渡口和集市入口偶尔用逆风环减缓争先拥挤的人流，让挑担者依次通过。赶车人则抱怨车轮迟滞会耽误行程，常要求留出足够宽的通道。若环带使运货马车延误而致鲜货损坏，港务会追究设置者的责任；在城内主要街道长时间布置，须先取得公会许可，以免妨碍消防和救护通行。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时所画环带常偏向一侧，行人仍可侧身快步穿过。",
        "百点后两弧能合拢成均匀环带，阻力覆盖整段路面。",
        "三百点以上可把环带压低到只挡脚步，不扰车顶货物。",
        "六百点后环带边界清晰，仍不增加任何伤害或推力。"
      ]
    }
  ]
}
